def f(inst, title, url):
    return {'institution': inst, 'title': title, 'url': url}


def voce(tipo, id, name, a, b, conf, summary, region, sub, lat, lon, label, layer, rel, area, typ, fonti, nota,
         related=(), place=None, prec='range'):
    r = dict(tipo=tipo, id=id, name=name, start_year=a, end_year=b, date_confidence=conf, summary=summary,
             region=region, subregion=sub, lat=lat, lon=lon, label=label, layer=layer, relevance=rel,
             world_area=area, related=list(related), fonti=fonti, nota='Voce nuova. ' + nota, data=D)
    r['entity_type' if tipo == 'entity' else 'event_type'] = typ
    if tipo == 'event':
        r['place_name'] = place or sub
    if prec == 'range' and a == b:
        prec = 'year'
    if prec:
        r['date_precision'] = prec
    return r


BK = 'https://www.britannica.com/'
BKS = 'https://kids.britannica.com/'
CL = ' Le coordinate del punto sono da conoscenza generale e scelte da Claude come riferimento.'


def b(title, path):
    return f(B, title, BK + path)


def bs(title, path):
    return f(BS, title, BKS + path)


